/*
 * A041437  Denominators of continued fraction convergents to sqrt(234).
 * https://oeis.org/A041437
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = 10402*a(n-8) - a(n-16) for n > 15 The first 16 terms are
 *            generated by the continued fraction of sqrt(234)
 * Range:     u8 n <= 6, u16 n <= 9, u32 n <= 21, u64 n <= 39, u128 n <= 78,
 *            big any n
 * Helpers:   ensure_cache
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include "../utils/ensure_cache.h"

/* dynamic cache for memoisation */
static seq_t * _cache   = NULL;
static size_t   _cap    = 0;
static idx_t    _max_n  = 0;           /* highest index computed so far */
static bool     _init   = false;       /* true when base terms are ready */

static void compute_base_terms(void)
{
    /* the period of sqrt(234) is 8; we need 16 terms (indices 0..15) */
    const size_t base_cnt = 16;

    /* ensure cache space */
    ensure_cache(base_cnt - 1, &_cache, &_cap);
    _max_n = base_cnt - 1;

    /* continued‑fraction partial quotients for sqrt(234) */
    const idx_t D      = 234ULL;
    const idx_t sqrtD  = 15ULL;          /* floor(sqrt(234)) */
    idx_t m = 0, d = 1, a = sqrtD;      /* current values for the CF algorithm */

    /* store quotients and compute convergents on the fly */
    seq_t p_prev2 = 0, p_prev1 = 1;      /* p_{-2}, p_{-1} */
    seq_t q_prev2 = 1, q_prev1 = 0;      /* q_{-2}, q_{-1} */

    for (size_t k = 0; k < base_cnt; ++k)
    {
        /* denominator of the k‑th convergent */
        seq_t q_curr = (seq_t)a * q_prev1 + q_prev2;
        _cache[k]    = q_curr;

        /* numerator for completeness (not used further) */
        seq_t p_curr = (seq_t)a * p_prev1 + p_prev2;

        /* shift for next step */
        p_prev2 = p_prev1;  p_prev1 = p_curr;
        q_prev2 = q_prev1;  q_prev1 = q_curr;

        /* compute next partial quotient */
        idx_t m_next = d * a - m;
        idx_t d_next = (D - m_next * m_next) / d;
        idx_t a_next = (sqrtD + m_next) / d_next;

        m = m_next;
        d = d_next;
        a = a_next;
    }
}

seq_t a(idx_t n)
{
    /* initialise base terms on first call */
    if (!_init)
    {
        compute_base_terms();
        _init = true;
    }

    /* already computed? */
    if (n <= _max_n)
        return _cache[n];

    /* grow cache up to required index */
    ensure_cache(n, &_cache, &_cap);

    /* fill missing terms using the recurrence */
    for (idx_t i = _max_n + 1; i <= n; ++i)
    {
        _cache[i] = (seq_t)10402 * _cache[i - 8] - _cache[i - 16];
    }

    _max_n = n;
    return _cache[n];
}
